head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > footerCaption]<br/>GridView 컴포넌트의 Footer Table 에 caption 요소를 설정합니다.",
    "validation" : [
        "GridView 컴포넌트의 Footer Table 에 caption 요소를 설정합니다. footerCaption 속성 설정 시 footerCaptionAuto 속성은 무시됩니다.",
        "Footer Table 의 caption 요소에 적용될 텍스트를 설정합니다.",
        "footerCaption 속성을 설정하지 않으면 Footer Table 에 caption 요소가 생성되지 않습니다. 단, footerCaptionAuto=true 일때 captionTitle 속성이 설정되어 있으면 '{captionTitle}합계를 나타낸 표' 값으로 caption 요소가 생성됩니다.",
        "setFooterCaption() 메소드는 렌더링 된 caption 값만 변경하며 footerCaption 값은 변경하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_footerCaption     : 문자열. 빈 값이면 footerCaption 속성을 아예 부여하지 않음(미설정)
    //  - con_footerCaptionAuto : 미설정('') / true / false. @spec1 의 auto caption 동작 확인용
    //  - con_captionTitle      : 문자열. 빈 값이면 captionTitle 속성을 부여하지 않음
    let footerCaptionVal     = con_footerCaption.getValue();
    let footerCaptionAutoVal = con_footerCaptionAuto.getText();
    let captionTitleVal      = con_captionTitle.getValue();

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 조건부 속성 (빈/미설정은 생략)
    let footerCaptionAttr     = (footerCaptionVal     === '') ? '' : 'footerCaption="'     + footerCaptionVal     + '" ';
    let footerCaptionAutoAttr = (footerCaptionAutoVal === '') ? '' : 'footerCaptionAuto="' + footerCaptionAutoVal + '" ';
    let captionTitleAttr      = (captionTitleVal      === '') ? '' : 'captionTitle="'      + captionTitleVal      + '" ';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFooterCaption     = (footerCaptionVal     === '') ? '미설정' : footerCaptionVal;
    let lblFooterCaptionAuto = (footerCaptionAutoVal === '') ? '미설정' : footerCaptionAutoVal;
    let lblCaptionTitle      = (captionTitleVal      === '') ? '미설정' : captionTitleVal;
    $c.gcm.createLabel('label="footerCaption=' + lblFooterCaption + ' / footerCaptionAuto=' + lblFooterCaptionAuto + ' / captionTitle=' + lblCaptionTitle + ' 로 GridView 생성 (Header 4컬럼 + gBody + Footer 1행)"', '', 'label1');

    // target 생성 (footerCaption / footerCaptionAuto / captionTitle 조건부, Footer Table 포함)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + footerCaptionAttr + footerCaptionAutoAttr + captionTitleAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="footerCaption 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Footer Table 의 caption 요소 텍스트를 DOM 으로 읽어 반환 (없으면 null)
scwin.getFooterCaptionText = function () {
    let footTable = document.querySelector("table[id*='target1_foot_table']");
    if (!footTable) {
        return null;
    }
    let caption = footTable.getElementsByTagName("caption")[0];
    return caption ? caption.textContent : null;
}



// 현재 Footer Table caption 요소 / footerCaption 속성값 확인 (@description / @propval / @spec1)
scwin.btn_checkFooterCaption_onclick = function () {
    let captionText = scwin.getFooterCaptionText();
    wf_body_bottom.getObj("scwin").setReturnValue("렌더 caption 요소 : " + (captionText === null ? '미생성(caption 요소 없음)' : "'" + captionText + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("footerCaption 속성값 : '" + target1.options.footerCaption + "'");
}



// setFooterCaption 호출 후 렌더 caption 과 footerCaption 옵션값을 함께 출력 (@spec2)
scwin.btn_setFooterCaption_onclick = function () {
    let val = par_setFooterCaption.getValue();
    target1.setFooterCaption(val);

    // 렌더링된 footer caption 텍스트만 변경됨 / footerCaption 속성값은 미변경 (@spec2)
    wf_body_bottom.getObj("scwin").setReturnValue("setFooterCaption('" + val + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("[렌더 caption(setFooterCaption 으로 변경됨)] " + scwin.getFooterCaptionText());
    wf_body_bottom.getObj("scwin").setReturnValue("[footerCaption 속성값(미변경)] '" + target1.options.footerCaption + "'");
}
